import{_ as e,c as p,o as r,af as h}from"./chunks/framework.BKeRpnBD.js";const b=JSON.parse('{"title":"明夷","description":"高島易斷 - 明夷","frontmatter":{"title":"明夷","description":"高島易斷 - 明夷"},"headers":[],"relativePath":"classics/takashima/036.md","filePath":"classics/takashima/036.md"}'),i={name:"classics/takashima/036.md"};function l(n,a,d,t,s,c){return r(),p("div",null,[...a[0]||(a[0]=[h('<h1 id="明夷" tabindex="-1">明夷 <a class="header-anchor" href="#明夷" aria-label="Permalink to “明夷”">​</a></h1><h2 id="明夷-1" tabindex="-1">明夷 <a class="header-anchor" href="#明夷-1" aria-label="Permalink to “明夷”">​</a></h2><h2 id="卦辭" tabindex="-1">卦辭 <a class="header-anchor" href="#卦辭" aria-label="Permalink to “卦辭”">​</a></h2><p>明夷：利艱貞。</p><h2 id="卦辭注" tabindex="-1">卦辭注 <a class="header-anchor" href="#卦辭注" aria-label="Permalink to “卦辭注”">​</a></h2><p>《明夷》，明受夷也。卦體上《坤》下《離》，《坤》地《離》火，火入地中，則火為土掩，火光不能上炎而生明，是火為土所克，而《離》火受傷。火既受傷，勢不能出《坤》而自炫其明道，惟晦而已矣。“艱”，以斂其彩，“貞”，以匿其光，退而避傷，潛以為利，是用晦之道也，故曰“明夷，利艱貞”。</p><h2 id="象辭" tabindex="-1">象辭 <a class="header-anchor" href="#象辭" aria-label="Permalink to “象辭”">​</a></h2><p>明入地中，明夷，君子以蒞眾，用晦而明。</p><h2 id="象辭注" tabindex="-1">象辭注 <a class="header-anchor" href="#象辭注" aria-label="Permalink to “象辭注”">​</a></h2><p>《離》為明，坤為地，“明入地中”，光明藏而不用之象，君子則之。《坤》為眾，故曰“蒞眾”，以御其眾也。知不可不明，亦不可以過明，不明則人皆欺我，過明則物不我容，所當納明智之德，於寬柔之中，韜其光而不露，蘊其美而自全，斯上不至妒其功，眾皆得以服其化。以此履盛，盛而益顯，以此涉危，危亦得安。古之聖賢，旒纊以塞聰明，樹屏以蔽內外，不欲明之過用者，胥是道也。</p><h2 id="占斷" tabindex="-1">占斷 <a class="header-anchor" href="#占斷" aria-label="Permalink to “占斷”">​</a></h2><p>○　問時運：運當大難，深宜晦藏。</p><p>○　問戰徵：《象》曰“蒞眾”，適值用師之時，宜效明修棧道暗度陳倉之計，必得勝也。</p><p>○　問營商：卦象艱難，大眾恐難取利，暗中尚有分肥。</p><p>○　問功名：《離》火被土所克，功名不顯，顯則反有災害。</p><p>○　問家宅：家道不順，或父子分居，尚可保全。</p><p>○　問婚姻：必非明媒正娶。</p><p>○　問疾病：是肝火內鬱之症，治宜熄火。</p><p>○　問訟事：宜受曲罷訟，可以免禍。</p><p>○　問六甲：生女。</p><h2 id="初九解" tabindex="-1">初九解 <a class="header-anchor" href="#初九解" aria-label="Permalink to “初九解”">​</a></h2><p>“于飛，垂其翼”者，謂飛鳥傷翼而下垂。“君子於行，三日不食”者，謂倉促決去，而無可得食。“有攸往”者，去此曰行，適彼曰往。“主人有言”者，謂或議其迂闊，或諷其偏固，雖未定其何辭，要不免嘖有煩言也。初爻與四為害應，被四所傷，《離》為飛鳥，故取以為喻。鳥遭傷而不得安棲，欲去而避其害，故曰“明夷于飛，垂其翼”。但初當《離》之始，去上猶遠，受傷尚淺，其去也，見風猶早。“三日不食”，《離》為大腹，其體中虛，中虛則腹空，不食之象。“三日”者，以《離》三爻皆明而見夷，故曰“三日”。君子接續而行，謂既去其國，不食其粟，故《傳》曰“義不食也”。“君子”，謂初也；“主人”，謂四也。初與四應，四欲傷初，初為避四而遠行，四見初去而有言，如初者可謂明於見幾，而不受四之所傷，真善用其晦者矣。</p><h2 id="初九佔" tabindex="-1">初九佔 <a class="header-anchor" href="#初九佔" aria-label="Permalink to “初九佔”">​</a></h2><p>○　問時運：初運不佳，惟其善自保全，得以無害。</p><p>○　問戰徵：為營中糧食已盡，且宜暫退。</p><p>○　問營商：《明夷》者，恐資本有傷，運貨遠行，有中途受難之象，又恐主人嘖有煩言也。</p><p>○　問功名：于飛垂翼，明示以不能騰達之象。</p><p>○　問婚姻：初爻與四相應，而反相害，婚姻不諧。</p><p>○　問家宅：此宅必是租典，非己屋也，故有主人；“三日不食”，有破灶不炊之象，不利，宜遷。</p><p>○　問六甲：生女。</p><h2 id="初九案例" tabindex="-1">初九案例 <a class="header-anchor" href="#初九案例" aria-label="Permalink to “初九案例”">​</a></h2><p>有友人某甲趕來，請佔氣運，筮得《明夷》之《謙》。</p><p>斷曰：《明夷》，《離》火被《坤》土所掩，明受傷也；《離》又有離散之義。《觀》足下相貌，骨間有黑氣所蒙，是明被黑掩，知將與主人離散矣，故爻曰“主人有言”。玩初爻之辭，顯見足下與主人不諧，意欲辭去。爻曰“于飛，垂其翼”，恐欲行而為主家所纏束，故垂翼而不能飛也。即從此他往，恐前途不利，尚有子胥吹簫之難。時運不佳，宜匿跡避禍。</p><p>明治二十八年，佔我國氣運，遇《明夷》之《謙》，呈之內閣總理大臣。</p><p>斷曰：此卦日入地中，為昏暮之時。就我國近時論之，《離》火之文明，盛於內地，逼於外國之交際，未能如意，故曰“明夷，利艱貞”。今者我軍戰勝清國，餘曾於本年六月初次啟佔，佔得《需》卦，知海陸軍之全勝；並料後日有三國干涉之議，外或以威武為頌揚，內實以富強生嫉妒，是各國之狡計也。今得此卦，知我軍當此戰勝之餘，軍艦或有損傷，而不適於用，兵士或有疲敝，而不可復勞，則猶如鳥之傷翼而不能飛揚，謂之“明夷于飛，垂其翼”。計欲進而相抗，無如兵力之不足何？計欲退而議和，無如國民之不服何？日夜籌思，幾廢寢食，謂之“三日不食”。爻象所謂“用晦而明”者，是指我所向往也；謂之“有攸往，主人有言”者，即指三國煩言也。果哉！四月媾和之約成，同時有三國之干涉，我遂還付遼東，得償金而結局。</p><h2 id="六二解" tabindex="-1">六二解 <a class="header-anchor" href="#六二解" aria-label="Permalink to “六二解”">​</a></h2><p>二為臣位，居《離》之中，與五相應，五《坤》為暗主，反欲傷害賢臣，是《明夷》之所以為《明夷》也。“左股”者，以二為股肱之臣，《管子·宙合》曰，“君立於左，臣立於右，君臣之分，左陽右陰”，以君在左，故二之所傷在左股也，故曰“明夷，夷於左股”。“用拯”者，與換初辭同，拯，救也，助也，子夏作升。二動體《乾》，《乾》為馬，乾健故“馬壯”，所謂用馬以自拯拔也。雖傷反吉。《象傳》曰“順以則也”，《坤》為順，以順則之，是承乾也，即取《乾》馬用拯之義。或謂二爻中虛，即內文明之象，卦屬周文，文居西岐，視紂都為左，故喻取左股；文囚羑里，當時貢以文馬九駟，是謂用拯實事。義殊精切。</p><h2 id="六二佔" tabindex="-1">六二佔 <a class="header-anchor" href="#六二佔" aria-label="Permalink to “六二佔”">​</a></h2><p>○　問時運：目下運不甚佳，頗有傷殘，幸得祿馬相救，故吉。</p><p>○　問戰徵：左營之軍不利，幸馬隊得力，得以轉敗為勝。</p><p>○　問營商：按策劃不適時宜曰左計，知其營謀不合時，故有損失，幸得有馬姓人出而調劑，則吉。</p><p>○　問功名：凡官級以降曰左，似不利也；惟值午年，或交午運，則吉。</p><p>○　問疾病：《離》二中虛，如陷進然，其人必陷入深坑；傷其左足，幸馬力壯健，得一躍而出，雖傷亦吉。</p><p>○　問家宅：必在左邊柱足損傷，宜急修治。</p><p>○　問婚姻：《離》陰象，女子恐有足疾，不良於行，宜配午命人吉。</p><p>○　問六甲：生女。</p><h2 id="六二案例" tabindex="-1">六二案例 <a class="header-anchor" href="#六二案例" aria-label="Permalink to “六二案例”">​</a></h2><p>明治二十二年，古某貴顯氣運，筮得《明夷》之《泰》。</p><p>斷曰：《明夷》《象》曰“明入地中”，是為入夕之時。人生命運，以嚮明為盛，以入夕為衰。今君佔氣運，得《明夷》二爻，推玩爻辭所云，恐君目下運限，未免有損傷刑剋。左道邪僻之徒，切不可近；行路時宜小心，防左足有跌傷之患；並慮瘡疾。大運須交午運乃佳，或逢午年，或值五月，皆利。</p><h2 id="九三解" tabindex="-1">九三解 <a class="header-anchor" href="#九三解" aria-label="Permalink to “九三解”">​</a></h2><p>三居《離》位之終，南者《離》之本位，狩者冬獵，守地而取之也。自《離》而《坤》為向西，《坤》傷明不可往，故曰“南狩”。《離》為兵戈，不曰行師，而曰狩田，亦託言從獸以自晦耳。按：《離》卦上六，曰“王用出徵，有嘉折首”，首謂魁首，是惡之大者也。今曰“得其大首”，必是獸之大者？獲其大而舍其小，即聖人網開一面之意，於此可見離明之仁德也。“疾”，數也，因狩講武，固事之正，然數數為之，非特犯從獸無厭之戒，抑且涉日討軍疲之忌，非用晦之道也，故曰“不可疾，貞”；《象傳》曰“南狩之志，乃大得也”，謂當此明夷之時，猶得於田行狩，私豵獻豕拜，嫌隙不生，得適其晦藏之志，亦大幸矣。一說“南狩”，謂即文王獵於南陽，得遇太公，以得大首，喻太公也。足備一解。</p><h2 id="九三佔" tabindex="-1">九三佔 <a class="header-anchor" href="#九三佔" aria-label="Permalink to “九三佔”">​</a></h2><p>○　問時運：大運不無破敗，是宜退守；交冬令，從南出行，必得大利。</p><p>○　問戰徵：卦曰《明夷》，明曰進兵，必有傷敗，宜潛兵從南而入。《離》上爻曰，“王用出徵，有嘉折首”，即合此佔。</p><p>○　問功名：南方屬文明，獵獸獵名，皆期其得。“大首”，魁首也，其必膺首選乎？故曰“志大得也”。吉。</p><p>○　問婚姻：婚禮奠雁射雀，亦取從禽之象，“得其大首”者，謂得其嘉偶。吉。</p><p>○　問疾病：當出避南方。吉。</p><p>○　問失物：可就宅南尋之，必得。</p><p>○　問六甲：生女。</p><p>○　問家宅：此宅《離》位南向，“大首”者，一鄉之大富家也。吉。</p><h2 id="九三案例" tabindex="-1">九三案例 <a class="header-anchor" href="#九三案例" aria-label="Permalink to “九三案例”">​</a></h2><p>明治十六年，某商人來，請佔氣運，筮得《明夷》之《復》。</p><p>斷曰：《明夷》，“明入地中”，《離》為日，日入《坤》土之中，明受其傷，故曰《明夷》。“夷者，傷也”，以論人生氣運，是目下運被傷害，本不見佳。足下商人，以商業論之，當於冬季，可往南海道一帶收賣貨物，必有一種大檔生意，可以獲利。然不宜再往，謂之“明夷於南狩，得其大首，不可疾貞”。後果得大利雲。</p><p>明治二十七年八月二十六日，佔平壤進軍，筮得《明夷》之《復》，乃贈之於某氏。</p><p>斷曰：此卦內卦日，外卦地，是太陽旋入地中之時。古來說卦者，以此爻為武王之事，曰“於南狩，得其大首”，謂言周之伐商，得其全勝。今佔平壤進兵，而得此爻，九月十五日，我軍自四面圍擊平壤，自南而北者，為大島少將之隊，戰甚苦，少將亦被銃傷，此應在《明夷》，夷，傷也。自北而南者，為佐藤大佐之隊，得其大勝，陷牡丹臺，逼玄武門，遂殪敵將左寶貴，敵軍悉潰，十六日曉，不損一兵，而取平壤。曰“南狩”，曰“得其大首”，一一中的，《易》理之玄妙如此！</p><h2 id="六四解" tabindex="-1">六四解 <a class="header-anchor" href="#六四解" aria-label="Permalink to “六四解”">​</a></h2><p>四爻出《離》入《坤》，《坤》為大腹。按卦位，《坤》在《離》之西，為左，“入於左腹”者，即入於《坤》之腹也。入其腹中，自可獲其心意，乃不曰獲《坤》之心，而曰“獲明夷之心”；“明夷”者，合全卦而言，即為“用晦而明”之心，是能卑順不逆，可效腹心之用者矣。“出”，出《離》也，《坤》方來，故曰“入於”；《離》已退，故曰“於出”。又初之六為《艮》，《艮》為門庭，門庭光明之地，“於出門庭”，亦即取“用晦而明”之義。一說“於出門庭”，謂即微子去之之象。《明夷》一卦，分配周興商亡，厲歷可證。</p><h2 id="六四佔" tabindex="-1">六四佔 <a class="header-anchor" href="#六四佔" aria-label="Permalink to “六四佔”">​</a></h2><p>○　問時運：爻象出明入暗，知為不利，不宜居家，還宜出門。</p><p>○　問戰徵：可潛入敵之左營，探聽密計，出告大營，可勝也。</p><p>○　問功名：功名以高升為吉，“入於左腹”，《坤》為腹，是入於地也。不吉。</p><p>○　問營商：釋名，“腹”，復也，富也。入於腹，即入於富也；獲心，即稱心也；“於出門庭”，是出家經商之象。</p><p>○　問疾病：是病在心腹，恐是內損之症，宜出門求醫。</p><p>○　問家宅：此宅明堂左首，路有阻礙，出入不便。</p><p>○　問婚姻：女子腹已有孕，不利。</p><p>○　問六甲：生女。</p><h2 id="六四案例" tabindex="-1">六四案例 <a class="header-anchor" href="#六四案例" aria-label="Permalink to “六四案例”">​</a></h2><p>縉紳某來，請佔氣運，筮得《明夷》之《豐》。</p><p>斷曰：時運宜陽不宜陰，宜明不宜暗，卦象曰《明夷》，“明入地中”，是向暗入夜。今得第四爻，據爻辭所言，料知貴下執事中，必有腹非小人，隱探貴下心意，藉端生事，出告於長官，致長官有疑於貴下，遂使事事多有掣肘。此皆目下氣運之不利也，不如退身避禍。後依所佔，轉懇友人陳告長官，長官諾之，使之轉任他局雲。</p><h2 id="六五解" tabindex="-1">六五解 <a class="header-anchor" href="#六五解" aria-label="Permalink to “六五解”">​</a></h2><p>《宋世家》曰：紂為淫佚，箕子諫之不聽。人或曰；可以去矣。箕子曰：諫不聽而去，是彰君之惡，而自悅於民，吾不忍也。乃披髮佯狂而為奴，遂隱而鼓琴。即此可見箕子之貞也。《彖傳》曰，“內難而能正其志，箕子以之”，五爻居上卦之中，故屬之箕子，上承《彖傳》之意，以釋“用晦”之義。《彖傳》所謂“內難”者，以紂為同姓也；所謂“正其志”者，即“利貞”也。《象傳》曰“明不可息”，謂《洪範·九疇》，其道萬古常明，箕子能陳之於周，故雖暫夷而終必明也，是之謂“明不可息”也。</p><h2 id="六五佔" tabindex="-1">六五佔 <a class="header-anchor" href="#六五佔" aria-label="Permalink to “六五佔”">​</a></h2><p>○　問時運：目下正當困厄，不失其正，久後必亨。</p><p>○　問戰徵：主師不明，致有謀士逃亡之象。</p><p>○　問營商：必歷經艱苦，方可獲利。</p><p>○　問功名：時事日艱，不宜於進，只宜退守。</p><p>○　問家宅：主親族不和。</p><p>○　問疾病：防有發狂之症。</p><p>○　問婚姻：宜罷婚。</p><p>○　問訟事：一時不直，久後自然明白。</p><p>○　問六甲：生女。</p><h2 id="六五案例" tabindex="-1">六五案例 <a class="header-anchor" href="#六五案例" aria-label="Permalink to “六五案例”">​</a></h2><p>明治十八年五月，應千家大教正之命，筮佛教之氣運，得《明夷》之《既濟》。</p><p>斷曰：佛法者，印度之聖人，了達三世，其道法靈妙高遠，世界宗教中，無出其右者也，自足昭明萬世，終古不息。今佔得此爻，爻辭曰“箕子之明夷，利貞”，箕子為紂庶兄，因紂無道，諫之不聽，乃佯狂為奴而避位，迨周興，陳《洪範·九疇》，得封，存殷之祀，是其道雖夷而終明也。現在佛法氣運，亦猶是商道衰微之時，千家大教正，猶是當日之箕子也，當守其教道之貞，以明其宗旨之傳，使釋迦之聖德常明，菩提之宗風不滅，皆賴大教正之力也。《象傳》曰“明不可息也”，斯之謂也！於是千家大教正嘆曰：“嗚呼！神佛二道氣運，果如此乎？不勝感悟！”</p><h2 id="上六解" tabindex="-1">上六解 <a class="header-anchor" href="#上六解" aria-label="Permalink to “上六解”">​</a></h2><p>上六居《坤》之極，為《明夷》一卦之主，是謂昏君，故“不明”而又加之曰“晦”，言昏之又昏者也。初“登天”，後“入地”，是始之自曜其明，卒之“明入於地”，為《明夷》之實象也。《彖傳》所稱文王箕子，其聖德之光明，豈不足以照四國？而當日文囚於羑里，箕佯狂為奴，正所謂入地者是也。故明夷之世，昏君在上，以入地者為用晦，登天者為失則。彼世之不審時勢，而急求登進，光照未遍，而身敗名滅，禍皆自取耳。必如文王之“柔順”“《蒙》難”，箕子之“內難”“正志”，斯為善處明夷者矣。《明夷》六爻，皆教人以“用晦”之方，昏君之兇，不言可知。</p><h2 id="上六佔" tabindex="-1">上六佔 <a class="header-anchor" href="#上六佔" aria-label="Permalink to “上六佔”">​</a></h2><p>○　問時運：初運雖好，後運不佳，萬事宜作退一步想，方可無咎。</p><p>○　問功名：宜晦藏遁跡，不宜自炫才華。</p><p>○　問營商：貨價初次太昂，落後太賤，顯有天淵之隔，宜得其平。</p><p>○　問戰徵：防攻山奪險，有墜入深淵之患。</p><p>○　問婚姻：有先富後貧之嫌。</p><p>○　問家宅：此宅面對高山，後臨深淵，殊嫌地勢低陷。</p><p>○　問疾病：初患氣衝，後又下洩，難治。</p><p>○　問六甲：生女。</p><h2 id="上六案例" tabindex="-1">上六案例 <a class="header-anchor" href="#上六案例" aria-label="Permalink to “上六案例”">​</a></h2><p>明治二十一年六月，餘與坂田服部兩氏，合謀製造攝綿土所於尾州熱田，推坂田氏為社長。攝綿土製法，密合石灰與粘土，燒造而成。向來我國所用，皆仰外國輸入，每年約費數十萬元，設立制局，每年可減卻十萬元。且熱田所制之品，優於外國，大得聲價。二十三年春，佔該社之景況，得《明夷》之《賁》。</p><p>斷曰：攝綿土製法，本系粘土石灰兩物，合制而成，粘土取之汙溼地中，所謂“入地”者是也。不取其潔白，而取其黑澤，所謂“不明，晦”者是也。此土出地，歷經工匠融化鍛鍊，猶如“登天”也；煉成後，用以粉牆築地，儼然“後入於地”也。該社製出之品，工精物美，可得遠售外國，即《象傳》所謂“照四國也”。玩爻辭之意，合之攝綿土之製造販行，歷歷相符，該社之盛行可必也。閱數月，復佔一卦，仍得前爻，益知神之所示，無有異辭，靈妙誠堪畏服。</p>',108)])])}const m=e(i,[["render",l]]);export{b as __pageData,m as default};
